Translate("ptBR", "stormwind-city", {
	title = "Ventobravo",
	aliases = { "Cidade de Ventobravo" },
	sections = {
		{
			title = "Resumo",
			text = [=[Ventobravo é a capital do {link:kingdom-of-stormwind}Reino de Ventobravo{/link} e a maior cidade da {link:humans}humanidade{/link} ainda de pé no sul. Suas muralhas brancas se erguem na borda ocidental da {link:elwynn-forest}Floresta de Elwynn{/link}, e canais azuis correm entre seus distritos. Mercadores lotam o {link:trade-district}Distrito Comercial{/link}. Peregrinos sobem os degraus da {link:cathedral-of-light}Catedral da Luz{/link}. Acima de todos está o {link:stormwind-keep}Castelo de Ventobravo{/link}, de onde os reis do reino governam há gerações. A cidade é orgulhosa, rica e populosa. É também uma cidade sem o seu rei.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra o ano em que Ventobravo foi fundada. Suas raízes estão nas famílias de {link:arathor}Arathor{/link} que viajaram para o sul há muito tempo e ergueram um reino que chamaram de {link:azeroth}Azeroth{/link}. Ventobravo era o seu coração. Por séculos a cidade cresceu em paz, e a Igreja da {link:holy-light}Luz Sagrada{/link} fez dela uma das grandes sedes de sua fé. Então veio a {link:first-war}Primeira Guerra{/link}. A {link:horde}Horda{/link} órquica incendiou o reino e saqueou a capital, e o Rei {link:llane-wrynn}Llane Wrynn{/link} morreu dentro de seu próprio castelo. Os sobreviventes fugiram para o norte com Sir {link:anduin-lothar}Anduin Lothar{/link}, rumo a {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[Ventobravo foi reerguida depois da {link:second-war}Segunda Guerra{/link}, pedra por pedra, pela {link:stonemasons-guild}Guilda dos Pedreiros{/link}. Quando a {link:house-of-nobles}Casa dos Nobres{/link} se recusou a pagar por esse trabalho, os pedreiros se revoltaram, a Rainha {link:tiffin-wrynn}Tiffin Wrynn{/link} foi morta e os pedreiros foram expulsos. Eles se tornaram a {link:defias-brotherhood}Irmandade Défias{/link}.

Agora o Rei {link:varian-wrynn}Varian Wrynn{/link} desapareceu numa viagem diplomática, e ninguém na corte sabe dizer onde ele está. Seu filho pequeno, {link:anduin-wrynn}Anduin{/link}, detém o título de rei. O Grão-senhor {link:bolvar-fordragon}Bolvar Fordragon{/link} governa em seu nome como regente, e a nobre {link:katrana-prestor}Katrana Prestor{/link} está muitas vezes ao seu lado. O exército está longe. Os Défias atacam nas estradas fora das muralhas. Dentro das muralhas, os prisioneiros do {link:the-stockade}Cárcere{/link} se rebelaram contra seus guardas. Os agentes do {link:si-7}SI:7{/link} suspeitam que alguém na corte está ajudando a Irmandade.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O povo de Ventobravo.{/b} Mercadores, artesãos, marinheiros, escrivães e os refugiados das guerras.
• {b}A corte e os nobres.{/b} O regente, seus conselheiros e os senhores da {link:house-of-nobles}Casa dos Nobres{/link} se reúnem no {link:stormwind-keep}Castelo de Ventobravo{/link}.
• {b}O clero.{/b} Os sacerdotes e paladinos da {link:cathedral-of-light}Catedral da Luz{/link} servem sob o {link:archbishop-benedictus}Arcebispo Benedictus{/link}.
• {b}Os anões de Altaforja.{/b} Mantêm seu próprio bairro junto às muralhas da cidade, com suas forjas e o túnel para {link:ironforge}Altaforja{/link}.
• {b}Os magos.{/b} Os magos do {link:mage-quarter}Distrito dos Magos{/link} estudam e ensinam à vista do Castelo.
• {b}Gente oculta.{/b} O {link:si-7}SI:7{/link} trabalha nas sombras da {link:old-town}Cidade Velha{/link}. Bruxos se reúnem no porão de uma taverna, e pouca gente pergunta o que fazem ali.]=],
		},
		{
			title = "História",
			text = [=[• {b}O Reino Antigo.{/b} Por séculos Ventobravo foi a capital de um reino pacífico, governado pela casa Wrynn.
• {b}A Queda.{/b} Na {link:first-war}Primeira Guerra{/link} a {link:horde}Horda{/link} rompeu as defesas da cidade. {link:llane-wrynn}Llane{/link} foi morto e seu filho {link:varian-wrynn}Varian{/link} foi levado ao exílio.
• {b}A Reconstrução.{/b} Depois da {link:second-war}Segunda Guerra{/link} os exilados voltaram para casa, e os pedreiros reconstruíram a cidade sobre suas antigas fundações.
• {b}A Revolta.{/b} Os nobres não quiseram pagar os pedreiros. A disputa terminou em sangue e na morte da rainha.
• {b}Os Dias de Hoje.{/b} O rei está desaparecido. Uma criança ocupa o trono, um regente governa, e os inimigos do reino se tornam ousados dentro de casa.]=],
		},
		{
			title = "Saberes da Cidade",
			text = [=[• A nova Ventobravo foi construída sobre as ruínas da antiga. Muitos dos homens que ergueram suas muralhas hoje se escondem entre os {link:defias-brotherhood}Défias{/link}.
• Um queijeiro no {link:trade-district}Distrito Comercial{/link} não é apenas um queijeiro. Os que sabem qual porta usar dizem que o {link:si-7}SI:7{/link} vigia a cidade de dentro de sua loja.
• Navios agora partem de um novo porto na costa oeste da cidade, cruzando o mar até {link:auberdine}Auberdine{/link}, na {link:darkshore}Costa Negra{/link}.]=],
		},
	},
})

Translate("ptBR", "trade-district", {
	title = "Distrito Comercial",
	sections = {
		{
			title = "Resumo",
			text = [=[O Distrito Comercial é o bairro mais movimentado de {link:stormwind-city}Ventobravo{/link}. Suas ruas abrigam o banco, a casa de leilões, a estalagem chamada Gilded Rose e lojas de todos os ofícios. {link:morgan-pestle}Morgan Pestle{/link} vende suas poções aqui, e a família {link:elling-trias}Trias{/link} vende queijo. Grifos pousam na borda do distrito, trazendo cartas e viajantes de todo o reino. Por baixo de toda a barganha corre o comércio mais antigo da cidade, que é o boato. O que se ouve no Distrito Comercial ao meio-dia é sabido no Castelo ao anoitecer.]=],
		},
	},
})

Translate("ptBR", "cathedral-square", {
	title = "Praça da Catedral",
	sections = {
		{
			title = "Resumo",
			text = [=[A Praça da Catedral é a grande praça aberta no coração de {link:stormwind-city}Ventobravo{/link}. Em sua extremidade norte se ergue a {link:cathedral-of-light}Catedral da Luz{/link}, a maior casa da {link:holy-light}Luz Sagrada{/link} no sul. Em volta da praça ficam a Prefeitura, onde o arquiteto {link:baros-alexston}Baros Alexston{/link} mantém seu escritório, e os salões onde o clero e os paladinos da cidade treinam. Soldados fazem exercícios sobre as lajes. Peregrinos vêm rezar. A praça é o lugar onde Ventobravo se mostra como deseja ser vista: devota, ordeira e forte.]=],
		},
	},
})

Translate("ptBR", "old-town", {
	title = "Cidade Velha",
	sections = {
		{
			title = "Resumo",
			text = [=[A Cidade Velha fica no leste de {link:stormwind-city}Ventobravo{/link}, onde as ruas são estreitas e os prédios mais antigos do que no resto da cidade. Ali ficam o quartel da cidade e uma loja de armaduras para soldados. É também o lar do {link:si-7}SI:7{/link}. O {link:master-mathias-shaw}Mestre Mathias Shaw{/link} trabalha a partir do quartel, e seus agentes entram e saem por portas que a maioria dos cidadãos nunca percebe. Nos becos, as pessoas cuidam da própria vida e fazem poucas perguntas. Soldados recém-chegados à capital vêm aqui primeiro, para serem armados, alojados e enviados aonde o reino precisa deles.]=],
		},
	},
})

Translate("ptBR", "dwarven-district", {
	title = "Distrito dos Anões",
	sections = {
		{
			title = "Resumo",
			text = [=[O Distrito dos Anões fica no norte de {link:stormwind-city}Ventobravo{/link}, junto às muralhas da cidade. Os anões de {link:ironforge}Altaforja{/link} que vivem em Ventobravo mantêm este bairro como seu. Aqui estão as forjas mais barulhentas da cidade, um salão da {link:explorers-league}Liga dos Exploradores{/link} e a entrada do {red:deeprun-tram}Metrô Correfundo{/red}, que corre sob as montanhas até Altaforja. O distrito é um sinal da velha amizade entre os dois reinos. Seus ferreiros dizem, e não em voz baixa, que o melhor aço de Ventobravo é feito na sua rua.]=],
		},
	},
})

Translate("ptBR", "mage-quarter", {
	title = "Distrito dos Magos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Distrito dos Magos fica no sudoeste de {link:stormwind-city}Ventobravo{/link}, onde telhados violeta se erguem acima dos canais. O Wizard's Sanctum fica em seu coração, e ali os magos da cidade treinam seus alunos nas {link:arcane-magic}artes arcanas{/link}. Nem toda magia daqui é lícita. Sob a taverna chamada Slaughtered Lamb, bruxos se reúnem num porão e estudam poderes que a Igreja condena. Perto do distrito, junto aos canais, fica o portão sombrio do {link:the-stockade}Cárcere{/link}, onde os guardas foram empurrados até a porta pelos próprios prisioneiros.]=],
		},
	},
})

Translate("ptBR", "the-park", {
	title = "O Parque",
	sections = {
		{
			title = "Resumo",
			text = [=[O Parque é um bairro verde no noroeste de {link:stormwind-city}Ventobravo{/link}. Árvores antigas se erguem entre caminhos tranquilos. É o lugar mais calmo de uma cidade populosa, e fica logo abaixo das muralhas do {link:stormwind-keep}Castelo de Ventobravo{/link}. Os moradores vêm aqui para descansar, passear e conversar. Roy Lewells mantém um clube do livro ali perto. Seus membros se reúnem num porão depois do expediente para discutir história e ideias, com livros emprestados da {link:royal-library}Biblioteca Real{/link} e com refrescos que Roy tem prazer em dividir com quem o ajuda.]=],
		},
	},
})

Translate("ptBR", "stormwind-keep", {
	title = "Castelo de Ventobravo",
	aliases = { "Fortaleza de Ventobravo" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Castelo de Ventobravo fica na extremidade norte da cidade, sede dos reis da casa Wrynn. Sua sala do trono é guardada dia e noite. Ali o jovem {link:anduin-wrynn}Rei Anduin{/link} se senta ao lado do {link:bolvar-fordragon}Grão-senhor Bolvar Fordragon{/link}, e {link:katrana-prestor}Lady Katrana Prestor{/link} atende a ambos. O Castelo abriga também a {link:royal-library}Biblioteca Real{/link}, os escritórios da guarda da cidade e um jardim murado onde os senhores da corte passeiam. Nem toda conversa naquele jardim é feita para ouvidos leais.]=],
		},
	},
})

Translate("ptBR", "stormwind-harbor", {
	title = "Porto de Ventobravo",
	aliases = { "porto de Ventobravo" },
	sections = {
		{
			title = "Resumo",
			text = [=[O porto de Ventobravo voltou a ficar movimentado. Um novo navio agora cruza o mar de sua doca sul até {link:auberdine}Auberdine{/link}, nas praias da {link:darkshore}Costa Negra{/link}, levando suprimentos, cartas e viajantes entre o reino e as terras dos {link:night-elves}elfos noturnos{/link}. Escrivães contam a carga caixote por caixote, e nunca há estivadores suficientes. Guardas e artilheiros vigiam a água. Mercadores da cidade já mandaram parentes para o outro lado do mar para negociar em Auberdine, e cartas voltam no sentido contrário pedindo ajuda. Pela primeira vez em anos, a cidade olha para fora, através do mar.]=],
		},
	},
})

Translate("ptBR", "valley-of-heroes", {
	title = "Vale dos Heróis",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale dos Heróis é a grande entrada de {link:stormwind-city}Ventobravo{/link}. A estrada que vem da {link:elwynn-forest}Floresta de Elwynn{/link} atravessa uma longa ponte e passa entre estátuas altas antes de chegar ao portão principal da cidade. Todo viajante que chega a Ventobravo por terra passa sob elas. A guarda da cidade vigia de perto este lugar, pois o portão é a primeira defesa da capital e a primeira coisa que seus visitantes veem. Mensageiros dos marechais distantes do reino chegam aqui, e escudeiros levam suas notícias do portão até a sala do trono.]=],
		},
	},
})

Translate("ptBR", "cathedral-of-light", {
	title = "Catedral da Luz",
	aliases = { "Catedral da Luz Sagrada" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Catedral da Luz é a maior casa da {link:holy-light}Luz Sagrada{/link} no {link:kingdom-of-stormwind}Reino de Ventobravo{/link}. Ela se ergue acima da {link:cathedral-square}Praça da Catedral{/link}, no coração da cidade. O {link:archbishop-benedictus}Arcebispo Benedictus{/link} lidera a Igreja de seus salões. Sacerdotes ensinam os fiéis ali, e em suas câmaras laterais {link:grayson-shadowbreaker}Lorde Grayson Shadowbreaker{/link} treina os paladinos do reino.]=],
		},
		{
			title = "Guardiã de Relíquias",
			text = [=[A Catedral faz mais do que rezar. Coisas sagradas são trazidas para cá para ficarem seguras, e coisas amaldiçoadas são trazidas para serem purificadas. Quando o amaldiçoado Eye of Paleth foi recuperado, foi levado ao Arcebispo. Quando uma pequena estátua do Rei {link:terenas-menethil}Terenas Menethil{/link} foi encontrada no {link:wetlands}Pantanal{/link}, a Luz pareceu se reunir em volta dela, e ela também foi enviada à Catedral para ser guardada. Os fiéis de {link:stormwind-city}Ventobravo{/link} confiam que o que entra na Catedral será bem guardado.]=],
		},
		{
			title = "Os Servos da Catedral",
			text = [=[A Catedral é lar de mais gente do que seu Arcebispo. Bispos, irmãos e acólitos servem em seus salões. O Irmão Kristoff prepara ali seus sermões com livros da {link:royal-library}Biblioteca Real{/link}, e os paladinos de Lorde {link:captain-grayson}Grayson{/link} treinam dentro de suas paredes. A palavra da Igreja parte daqui para a {link:northshire-abbey}Abadia de Vila Norte{/link} e para cada capela do reino.]=],
		},
	},
})

Translate("ptBR", "royal-library", {
	title = "Biblioteca Real",
	aliases = { "Biblioteca de Ventobravo", "biblioteca de Ventobravo" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Biblioteca Real fica dentro do {link:stormwind-keep}Castelo de Ventobravo{/link}. Guarda a memória escrita do reino: histórias, tratados e os registros da corte. Seu guardião, {link:milton-sheaf}Milton Sheaf{/link}, manda buscar livros perdidos onde quer que se diga que estão, da {link:duskwood}Floresta do Crepúsculo{/link} às bibliotecas perdidas da caída {link:alterac-mountains}Alterac{/link}.]=],
		},
		{
			title = "O Empréstimo de Livros",
			text = [=[A biblioteca não guarda suas estantes só para os senhores. Empresta livros a estudiosos e ao clero, e nestes dias também troca volumes com um pequeno clube do livro da cidade. Os títulos que esse clube pede revelam o que o povo comum hoje se pergunta: relatos das incursões da {link:horde}Horda{/link}, as conquistas dos reis Matatroll e títulos ainda mais estranhos.]=],
		},
		{
			title = "Os Bibliotecários",
			text = [=[{link:milton-sheaf}Milton Sheaf{/link} cuida da biblioteca, e Donyal Tovald vigia suas estantes e seus empréstimos. São homens rigorosos. Espera-se que um livro que sai da biblioteca volte no mesmo estado, e quem trata um volume com respeito é bem-vindo para pedir outro, por mais provocadoras que sejam suas palavras.]=],
		},
	},
})

Translate("ptBR", "varian-wrynn", {
	title = "Varian Wrynn",
	subtitle = "O Rei Desaparecido de Ventobravo",
	found = "Em lugar nenhum; o rei desapareceu",
	hint = "Saiba do rei que Ventobravo perdeu.",
	allegiance = "Reino de Ventobravo · Casa Wrynn",
	aliases = { "Varian", "Rei Varian", "Rei Varian Wrynn" },
	sections = {
		{
			title = "Resumo",
			text = [=[Varian Wrynn é o Rei de {link:stormwind-city}Ventobravo{/link}, filho do Rei {link:llane-wrynn}Llane Wrynn{/link} e pai do jovem Anduin. Viu o reino de seu pai arder quando era menino, tornou-se homem no exílio e voltou para governar uma cidade reconstruída de suas cinzas. Agora ele se foi. Partiu numa viagem diplomática e nunca voltou, e nenhuma notícia sua chegou à corte.]=],
		},
		{
			title = "Importância",
			text = [=[A ausência de Varian molda toda {link:stormwind-city}Ventobravo{/link}. Uma criança detém seu título. Um regente governa em seu nome. Seu exército está longe, suas estradas são inseguras e seus nobres discutem nos salões do Castelo. Todo súdito leal do reino faz a mesma pergunta, e ninguém na corte sabe respondê-la: onde está o rei? Até que ele volte, Ventobravo precisa ser mantida pelos que estavam ao lado de seu trono.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ainda menino, sobreviveu à queda de {link:stormwind-city}Ventobravo{/link} na {link:first-war}Primeira Guerra{/link}, quando seu pai foi morto.
• Foi levado para o norte, a {link:lordaeron}Lordaeron{/link}, por Sir {link:anduin-lothar}Anduin Lothar{/link} e cresceu no exílio.
• Depois da {link:second-war}Segunda Guerra{/link}, voltou para assumir o trono de uma Ventobravo reconstruída.
• Casou-se com {link:tiffin-wrynn}Tiffin Wrynn{/link} e perdeu-a na revolta dos pedreiros.
• Partiu numa missão diplomática e desapareceu.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica registra o ano do desaparecimento de Varian, nem onde ele foi visto pela última vez. O que foi feito dele não se sabe em {link:stormwind-city}Ventobravo{/link}.]=],
		},
	},
	chapters = {
		{
			title = "O Retorno do Exilado",
			hint = "Saiba como Ventobravo foi reconstruída.",
			text = [=[O menino que fugiu da cidade em chamas voltou para casa um homem. {link:stormwind-city}Ventobravo{/link} fora reconstruída pelos pedreiros, e Varian foi coroado nos salões de seu pai. Tomou uma rainha, {link:tiffin-wrynn}Tiffin{/link}, e ela lhe deu um filho, a quem ele deu o nome do herói que lhe salvara a vida. Por um tempo, pareceu que a casa Wrynn havia atravessado o fogo.]=],
		},
		{
			title = "A Morte da Rainha",
			hint = "Saiba o que a revolta dos pedreiros custou ao rei.",
			text = [=[Quando a {link:house-of-nobles}Casa dos Nobres{/link} se recusou a pagar a {link:stonemasons-guild}Guilda dos Pedreiros{/link}, os pedreiros se levantaram em fúria. No caos daquela revolta, a {link:tiffin-wrynn}Rainha Tiffin{/link} foi morta. Os pedreiros foram expulsos da cidade, e o rei ficou para criar o filho sozinho. Do exílio dos pedreiros nasceu a {link:defias-brotherhood}Irmandade Défias{/link}.]=],
		},
		{
			title = "O Trono Vazio",
			hint = "Leve ao rei um relatório sobre a Irmandade Défias.",
			text = [=[O relatório era destinado às mãos do próprio rei. Falava da irmandade de {link:edwin-vancleef}VanCleef{/link} e da traição descoberta na corte. Mas o rei não estava lá para lê-lo. {link:katrana-prestor}Lady Prestor{/link} o recebeu em seu lugar e disse apenas que Varian estava ausente numa missão diplomática. Não disse para onde ele tinha ido.]=],
		},
	},
	mentions = {
		{ text = "An Audience with the King, um relatório endereçado a ele" },
	},
	bonds = {
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "seu filho" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "seu pai" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "sua rainha, perdida na revolta" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "levou-o ao exílio" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "governa em seu nome" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "fala pela corte em sua ausência" },
	},
})

Translate("ptBR", "anduin-wrynn", {
	title = "Anduin Wrynn",
	subtitle = "O Rei Menino de Ventobravo",
	found = "A sala do trono do Castelo de Ventobravo",
	hint = [=[Peça uma audiência na sala do trono do Castelo de Ventobravo.]=],
	allegiance = "Reino de Ventobravo · Casa Wrynn",
	aliases = { "Rei Anduin", "Príncipe Anduin" },
	sections = {
		{
			title = "Resumo",
			text = [=[Anduin Wrynn é o único filho do {link:varian-wrynn}Rei Varian{/link} e da {link:tiffin-wrynn}Rainha Tiffin{/link}. Ainda é uma criança, mas, com o pai ausente, detém o título de Rei de {link:stormwind-city}Ventobravo{/link}. Ele fica na sala do trono do Castelo entre homens feitos de armadura e damas da corte, enquanto o {link:bolvar-fordragon}Grão-senhor Bolvar Fordragon{/link} governa em seu nome.]=],
		},
		{
			title = "Importância",
			text = [=[Anduin é o futuro da casa Wrynn e a esperança viva de seu reino. Enquanto ele estiver na sala do trono, o povo de {link:stormwind-city}Ventobravo{/link} pode acreditar que sua linhagem de reis não foi rompida. Ele recebeu o nome de Sir {link:anduin-lothar}Anduin Lothar{/link}, o campeão que salvou seu pai quando menino e o tirou da cidade em chamas.

O lugar do menino é estranho. Ele detém o título mais alto do reino, mas as decisões do reino são tomadas por outros. Todo peticionário que entra na sala do trono se curva diante dele. Poucos falam com ele. Falam com o regente ao seu lado e com a dama da corte que fica perto de ambos. Anduin vê e ouve tudo isso.]=],
		},
		{
			title = "Feitos",
			text = [=[• Perdeu a mãe na revolta dos pedreiros quando era muito pequeno.
• Detém o título do pai enquanto o rei está desaparecido.
• Mantém a corte ao lado do regente e dos senhores do reino.
• Espera na sala do trono do pai por notícias do pai.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica registra o ano do nascimento de Anduin, nem sua idade exata nestes dias. Os registros da corte pouco dizem de seus próprios pensamentos.]=],
		},
	},
	chapters = {
		{
			title = "Uma Criança no Trono",
			hint = "Fale com o jovem rei no Castelo de Ventobravo.",
			text = [=[O menino aprendeu a ficar parado durante longas audiências. Ouve marechais e nobres, petições das fazendas e relatórios das fronteiras. Perdeu uma mãe e, talvez, um pai. A corte o chama de rei. Os que olham com atenção veem que ele é também uma criança, à espera de notícias que nunca chegam.]=],
		},
		{
			title = "Herdeiro de Duas Casas",
			hint = "Conheça a história da casa Wrynn.",
			text = [=[O avô de Anduin, o Rei {link:llane-wrynn}Llane Wrynn{/link}, morreu na queda da antiga {link:stormwind-city}Ventobravo{/link}. Seu pai cresceu no exílio na corte do {link:terenas-menethil}Rei Terenas{/link}, em {link:lordaeron}Lordaeron{/link}, e voltou para construir uma nova cidade. Sua mãe, a Rainha {link:tiffin-wrynn}Tiffin{/link}, morreu nas ruas dessa cidade. Anduin herdou tanto a coroa quanto suas feridas.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "seu pai, desaparecido" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "sua mãe" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "seu regente e protetor" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "uma dama de sua corte" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "o herói cujo nome recebeu" },
	},
})

Translate("ptBR", "bolvar-fordragon", {
	title = "Bolvar Fordragon",
	subtitle = "Regente de Ventobravo",
	found = "A sala do trono do Castelo de Ventobravo",
	hint = "Procure o Grão-senhor que governa da sala do trono.",
	allegiance = "Reino de Ventobravo · Luz Sagrada",
	aliases = { "Bolvar", "Grão-senhor Bolvar Fordragon", "Grão-senhor Fordragon", "Fordragon" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Grão-senhor Bolvar Fordragon é um campeão da {link:holy-light}Luz Sagrada{/link} e o regente de {link:stormwind-city}Ventobravo{/link}. Com o {link:varian-wrynn}Rei Varian{/link} desaparecido e seu filho ainda criança, Bolvar governa o reino da sala do trono do Castelo. Ele fica ao lado do jovem Anduin em armadura reluzente, e toda ordem que sai do {link:stormwind-keep}Castelo de Ventobravo{/link} sai sob o seu selo.]=],
		},
		{
			title = "Importância",
			text = [=[Bolvar mantém o reino unido em sua hora mais incerta. Precisa responder aos apelos de cada fronteira em apuros, de {link:redridge-mountains}Cristarrubra{/link} ao {link:wetlands}Pantanal{/link}, com um exército já esticado ao limite. Apoia-se no conselho dos que o cercam. Entre eles, ninguém é ouvido com mais frequência do que {link:katrana-prestor}Lady Katrana Prestor{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Governa {link:stormwind-city}Ventobravo{/link} como regente em nome do rei menino.
• Guarda Anduin pessoalmente, na sala do trono do Castelo.
• Recebe as petições das cidades e dos marechais do reino.
• Envia campeões para lidar com ameaças que o exército não consegue alcançar.]=],
		},
	},
	chapters = {
		{
			title = "O Apelo de Vila Plácida",
			hint = "Leve o apelo do magistrado de Vila Plácida ao regente.",
			text = [=[O {link:magistrate-solomon}Magistrado Solomon{/link}, de {link:lakeshire}Vila Plácida{/link}, escreveu ao regente sobre os perigos que cercavam {link:redridge-mountains}Cristarrubra{/link} e implorou ajuda à coroa. Bolvar não quis decidir sozinho. Primeiro mandou o mensageiro falar com {link:katrana-prestor}Lady Prestor{/link}, e só depois do conselho dela redigiu seu decreto para Vila Plácida.]=],
		},
		{
			title = "Uma Estátua do Velho Rei",
			hint = [=[Traga ao regente uma relíquia do Rei Terenas, vinda do Pantanal.]=],
			text = [=[Do {link:menethil-harbor}Porto de Menethil{/link}, no {link:wetlands}Pantanal{/link}, veio uma pequena estátua do Rei {link:terenas-menethil}Terenas Menethil{/link}, recuperada depois de uma longa busca. Os guardiões do porto temiam guardá-la numa terra cercada de inimigos. Enviaram-na direto a Bolvar, confiando que ele saberia onde tal lembrança do rei de {link:lordaeron}Lordaeron{/link} deveria ser guardada.]=],
		},
		{
			title = "O Senhor dos Patrulheiros",
			hint = "Leve ao regente notícias de Nathanos Marris.",
			text = [=[Chegaram ao Castelo notícias de {link:nathanos-blightcaller}Nathanos Marris{/link}, outrora senhor dos patrulheiros, que agora serve aos {link:forsaken}Renegados{/link} como Nathanos Blightcaller. Bolvar não tratou do assunto como coisa pequena. Pediu um exército para marchar sobre as {link:eastern-plaguelands}Terras Pestilentas Orientais{/link} e dar fim ao Blightcaller, e avisou que a {link:horde}Horda{/link} defenderia o senhor dos patrulheiros com a própria vida.]=],
		},
		{
			title = "O Grande Baile de Máscaras",
			hint = [=[Fique ao lado do Grão-senhor quando a verdade for revelada em sua própria sala do trono.]=],
			text = [=[O Marechal {red:reginald-windsor}Reginald Windsor{/red} veio à sala do trono com provas de uma conspiração no coração da corte. Quando ele falou, a mulher que por tanto tempo aconselhara Bolvar mostrou sua verdadeira forma. Ela era {link:onyxia}Onyxia{/link}, filha de {link:deathwing}Asa da Morte{/link}. Bolvar fora seu fantoche, e ela lhe disse isso na cara. Windsor caiu, e a dragoa fugiu. O que ela deixou para trás foi um regente abalado e uma corte que já não podia confiar nos seus.]=],
		},
	},
	mentions = {
		{ text = "The True Masters" },
		{ text = "The True Masters" },
		{ text = "A Friend of the Family" },
		{ text = "The First and the Last" },
		{ text = "The {link:nathanos-blightcaller}Blightcaller{/link} Cometh" },
		{ text = "Order Must Be Restored" },
		{ text = "The Great Masquerade" },
		{ text = "The Dragon's Eye" },
	},
	bonds = {
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "o rei menino que ele protege" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "o rei a quem serve" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "sua conselheira de maior confiança" },
		{ id = "master-mathias-shaw", name = "Mestre Mathias Shaw", note = "seu mestre-espião" },
		{ id = "major-samuelson", name = "Major Samuelson", note = "um oficial de sua guarda" },
	},
})

Translate("ptBR", "katrana-prestor", {
	title = "Katrana Prestor",
	subtitle = "Dama da Corte de Ventobravo",
	found = "A sala do trono do Castelo de Ventobravo",
	hint = "Procure a nobre que fica ao lado do regente.",
	allegiance = "Reino de Ventobravo · A Corte",
	aliases = { "Katrana", "Lady Katrana Prestor", "Lady Prestor" },
	sections = {
		{
			title = "Resumo",
			text = [=[Lady Katrana Prestor é uma nobre de grande influência. Ela fica na sala do trono do {link:stormwind-keep}Castelo de Ventobravo{/link} ao lado do {link:bolvar-fordragon}Grão-senhor Bolvar Fordragon{/link} e fala pela corte quando a corte precisa falar. Os peticionários que vêm ao Castelo muitas vezes descobrem que suas palavras só chegam ao regente depois de chegarem a ela.]=],
		},
		{
			title = "Importância",
			text = [=[Numa corte sem rei, o conselho de uma conselheira de confiança tem o peso da lei. A voz de Lady Prestor é ouvida em cada grande questão do reino: o que o reino pode ceder, em quem deve acreditar e quais de seus problemas podem ser ignorados sem perigo. Alguns no reino admiram sua sabedoria. Outros, longe da capital, começaram a se perguntar por que seus apelos tão raramente encontram resposta.

Ela está sempre presente. Quando o regente recebe uma petição, ela está ao seu lado. Quando chega um relatório para o rei ausente, é ela quem o recebe. Quando o regente precisa decidir, pede primeiro o conselho dela. Nenhum senhor da {link:house-of-nobles}Casa dos Nobres{/link} tem um lugar tão próximo do coração do reino.]=],
		},
		{
			title = "Feitos",
			text = [=[• Aconselha o regente nos assuntos do reino.
• Recebe os relatórios endereçados ao rei ausente.
• Diz a quem pergunta que o rei está ausente numa missão diplomática.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhum registro da corte diz de onde Lady Prestor veio, nem quando chegou pela primeira vez ao {link:stormwind-keep}Castelo de Ventobravo{/link}.]=],
		},
	},
	chapters = {
		{
			title = "O Relatório para o Rei",
			hint = "Leve ao rei um relatório sobre a Irmandade Défias.",
			text = [=[O relatório era endereçado ao {link:varian-wrynn}Rei Varian{/link}. Falava dos {link:defias-brotherhood}Défias{/link}, da traição de {link:gregor-lescovar}Lorde Gregor Lescovar{/link} e do assassino no jardim real. Lady Prestor o recebeu pessoalmente. Agradeceu a quem o trouxe e explicou que o rei estava ausente numa missão diplomática.]=],
		},
		{
			title = "Conselho ao Regente",
			hint = "Leve o apelo de Vila Plácida ao Castelo de Ventobravo.",
			text = [=[Quando {link:lakeshire}Vila Plácida{/link} implorou ajuda à coroa em {link:redridge-mountains}Cristarrubra{/link}, o regente não quis responder antes que Lady Prestor tivesse falado. Ela ouviu o apelo e deu seu conselho. Só então {link:bolvar-fordragon}Bolvar{/link} escreveu seu decreto.]=],
		},
		{
			title = "O Grande Baile de Máscaras",
			hint = "Veja a corte de Ventobravo como ela realmente é.",
			text = [=[Quando o Marechal {red:reginald-windsor}Reginald Windsor{/red} veio à sala do trono com suas provas, Lady Prestor zombou dele e mandou prendê-lo. Então ela se livrou do disfarce. Lady Katrana Prestor nunca fora nobre. Ela era {link:onyxia}Onyxia{/link}, filha de {link:deathwing}Asa da Morte{/link}, uma dragoa negra que usara um rosto humano na corte de {link:stormwind-city}Ventobravo{/link}. Durante todo o tempo em que esteve ao lado do regente, a Revoada {link:the-drag}Drag{/link}ônica Negra teve o ouvido do reino. Windsor morreu na sala do trono. Onyxia fugiu e deixou {link:bolvar-fordragon}Bolvar{/link} descobrir por quanto tempo fora seu fantoche.]=],
		},
	},
	mentions = {
		{ text = "An Audience with the King" },
		{ text = "The True Masters" },
		{ text = "The Great Masquerade" },
	},
	bonds = {
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "o regente que ela aconselha" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "o rei menino de sua corte" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "o rei que ela diz estar ausente" },
	},
})

Translate("ptBR", "archbishop-benedictus", {
