		},
		{
			title = "O Coldbringer",
			hint = [=[Atenda ao chamado do Arcebispo contra o lich do Urzal dos Mortos.]=],
			text = [=[Muito ao sul, em {link:kalimdor}Kalimdor{/link}, nos salões espinhosos dos {link:quilboar}javatuscos{/link}, uma criatura morta-viva chamada {link:amnennar-the-coldbringer}Amnennar the Coldbringer{/link} fez sua morada. Benedictus não espera que tal mal atravesse o mar. Pede campeões que busquem o Coldbringer e deem fim a ele em nome da Luz.]=],
		},
	},
	mentions = {
		{ text = "Cleansing the Eye" },
		{ text = "Bring the Light" },
	},
	bonds = {
		{ id = "grayson-shadowbreaker", name = "Grayson Shadowbreaker", note = "lidera os paladinos de sua catedral" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "ocupou o cargo antes dele" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "o regente de seu reino" },
	},
})

Translate("ptBR", "master-mathias-shaw", {
	title = "Mestre Mathias Shaw",
	subtitle = "Mestre do SI:7",
	found = "O quartel da Cidade Velha",
	hint = "Encontre o mestre do SI:7 no quartel da Cidade Velha.",
	allegiance = "Reino de Ventobravo · SI:7",
	aliases = { "Mathias Shaw", "Shaw" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Mestre Mathias Shaw lidera o {link:si-7}SI:7{/link}, o serviço secreto de {link:stormwind-city}Ventobravo{/link}. Do quartel da {link:old-town}Cidade Velha{/link} ele reúne relatórios de todo o reino, treina agentes nas artes da furtividade e os envia aonde soldados não podem ir. A maioria dos cidadãos de Ventobravo não conhece seu nome. A maioria de seus inimigos gostaria de não conhecer.]=],
		},
		{
			title = "Importância",
			text = [=[Com o exército no estrangeiro, os agentes de Shaw são os olhos do reino. Eles vigiam a {link:defias-brotherhood}Irmandade Défias{/link} em {link:westfall}Cerro Oeste{/link} e na {link:duskwood}Floresta do Crepúsculo{/link}, e vigiam a corte no {link:stormwind-keep}Castelo de Ventobravo{/link}. É Shaw quem descobre que o alcance da Irmandade vai além dos campos e das minas, até os salões da própria nobreza do reino.]=],
		},
		{
			title = "Feitos",
			text = [=[• Dirige os agentes do {link:si-7}SI:7{/link} contra os {link:defias-brotherhood}Défias{/link} em {link:westfall}Cerro Oeste{/link} e na {link:duskwood}Floresta do Crepúsculo{/link}.
• Treina os ladinos de {link:stormwind-city}Ventobravo{/link}.
• Desmascara o traidor {link:gregor-lescovar}Lorde Gregor Lescovar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Sombra do Passado",
			hint = [=[Leve ao Mestre do SI:7 a descrição do visitante de Bazil Thredd.]=],
			text = [=[Antes da revolta no {link:the-stockade}Cárcere{/link}, {link:bazil-thredd}Bazil Thredd{/link} recebeu um visitante. O carcereiro anotou o que viu desse visitante e lacrou o escrito. A descrição passou pelas mãos de {link:baros-alexston}Baros Alexston{/link} e chegou a Shaw. Ele a leu e soube que a trilha levava de volta à própria {link:stormwind-city}Ventobravo{/link}. Mandou avisar um velho amigo que vigia a cidade.]=],
		},
		{
			title = "A Cabeça da Fera",
			hint = "Ajude o SI:7 a desmascarar o traidor da corte.",
			text = [=[Quando o traidor Lorde {link:gregor-lescovar}Lescovar{/link} e seu contato {link:defias-brotherhood}Défias{/link} jaziam mortos no jardim real, a notícia chegou a Shaw. Foi uma vitória, mas não um fim. Um senhor da {link:house-of-nobles}Casa dos Nobres{/link} trabalhara com a irmandade de {link:edwin-vancleef}VanCleef{/link}, e Shaw enviou o relato completo ao Arquiteto da Cidade, para que chegasse ao rei.]=],
		},
	},
	mentions = {
		{ text = "The {link:defias-brotherhood}Irmandade Défias{/link}" },
		{ text = "The {link:defias-brotherhood}Irmandade Défias{/link}" },
