		{ id = "baros-alexston", name = "Baros Alexston", note = "divide com ele a luta contra os Défias" },
		{ id = "gregor-lescovar", name = "Gregor Lescovar", note = "o traidor que ele desmascarou" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "o regente a quem serve" },
	},
})

Translate("ptBR", "baros-alexston", {
	title = "Baros Alexston",
	subtitle = "Arquiteto da Cidade de Ventobravo",
	found = "Prefeitura, Praça da Catedral",
	hint = [=[Encontre o Arquiteto da Cidade na Prefeitura, na Praça da Catedral.]=],
	allegiance = "Reino de Ventobravo · Prefeitura",
	aliases = { "Baros", "Alexston" },
	sections = {
		{
			title = "Resumo",
			text = [=[Baros Alexston é o Arquiteto da {link:stormwind-city}Cidade de Ventobravo{/link}. Da Prefeitura, na {link:cathedral-square}Praça da Catedral{/link}, ele supervisiona a construção e o reparo da capital. Conhece as pedras de Ventobravo melhor do que qualquer senhor da corte, e conhece o preço que foi pago para erguê-las.]=],
		},
		{
			title = "Importância",
			text = [=[Baros está no cruzamento da ferida mais antiga de {link:stormwind-city}Ventobravo{/link}. A cidade de que ele cuida foi reconstruída pelos pedreiros que se tornaram a {link:defias-brotherhood}Irmandade Défias{/link}. Quando {link:edwin-vancleef}Edwin VanCleef{/link} escreveu uma carta que nunca enviou, ela era endereçada a Baros. Pelo arquiteto, a história da Irmandade passa das {link:the-deadmines}Minas Mortas{/link} ao {link:the-stockade}Cárcere{/link}, do {link:si-7}SI:7{/link} à sala do trono.]=],
		},
		{
			title = "Feitos",
			text = [=[• Mantém os prédios de {link:stormwind-city}Ventobravo{/link} em bom estado.
• Age a partir da carta de {link:edwin-vancleef}VanCleef{/link} e manda avisar o carcereiro do {link:the-stockade}Cárcere{/link}.
• Leva a luta contra a Irmandade ao {link:si-7}SI:7{/link} e à corte.
• Responde, como pode, aos apelos que chegam à cidade de costas distantes.]=],
		},
	},
	chapters = {
		{
			title = "Começos Humildes",
			hint = [=[Recupere a velha bússola do arquiteto em sua casa em Cerro Oeste.]=],
			text = [=[Baros teve um dia uma casa em {link:westfall}Cerro Oeste{/link}. Deixou algo para trás ali: uma velha bússola, a ferramenta de seu primeiro ofício. Cerro Oeste é perigoso agora, e suas fazendas caíram nas mãos de ladrões e na ruína. Mas um construtor não esquece o instrumento que primeiro lhe ensinou a traçar uma linha reta.]=],
		},
		{
			title = "A Carta Não Enviada",
			hint = [=[Traga ao arquiteto a carta encontrada entre os pertences de VanCleef.]=],
			text = [=[{link:edwin-vancleef}Edwin VanCleef{/link} escrevera uma carta a Baros e a lacrara, mas ela nunca saiu das {link:the-deadmines}Minas Mortas{/link}. Quando enfim chegou às mãos do arquiteto, ele a leu com cuidado. Suas palavras voltaram seus pensamentos para o {link:the-stockade}Cárcere{/link}, onde um dos tenentes de VanCleef, {link:bazil-thredd}Bazil Thredd{/link}, estava preso.]=],
		},
		{
			title = "Uma Carta de Auberdine",
			hint = [=[Leve a carta do ancião de Auberdine através do mar até Ventobravo.]=],
