	sections = {
		{
			title = "Resumo",
			text = [=[Lorde Grayson Shadowbreaker treina os paladinos de {link:stormwind-city}Ventobravo{/link} nos salões da {link:cathedral-of-light}Catedral da Luz{/link}. É cavaleiro e mestre, e seus alunos aprendem com ele que a {link:holy-light}Luz Sagrada{/link} pede sacrifício antes de conceder força. Os jovens paladinos do reino passam por suas mãos, e também os velhos, quando buscam um caminho mais difícil.]=],
		},
		{
			title = "Importância",
			text = [=[{link:captain-grayson}Grayson{/link} mantém viva a união entre fé e aço que a Igreja da {link:holy-light}Luz Sagrada{/link} forjou depois da {link:first-war}Primeira Guerra{/link}. Seu conselho vai além de {link:stormwind-city}Ventobravo{/link}. Ele envia jovens paladinos anões a seus próprios mestres em {link:ironforge}Altaforja{/link}, e a ele se confiam coisas sagradas que o reino deseja manter em segurança.]=],
		},
		{
			title = "Feitos",
			text = [=[• Treina os paladinos da Catedral.
• Envia paladinos anões a Tiza Battleforge, em {link:ironforge}Altaforja{/link}.
• Põe os paladinos provados do reino num longo caminho de provações e sacrifício.
• Recebe a Menethil Statuette para guardá-la na Catedral.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Pouco se escreveu sobre a vida de {link:captain-grayson}Grayson{/link} antes da Catedral, nem sobre os feitos que lhe renderam seu título.]=],
		},
	},
	chapters = {
