			hint = [=[Traga à Catedral uma pequena estátua do velho rei de Lordaeron.]=],
			text = [=[O Rei {link:terenas-menethil}Terenas Menethil{/link} era um homem humilde que não gostava de monumentos, e poucas imagens dele sobreviveram à queda de seu reino. Quando uma pequena estátua sua saiu do {link:wetlands}Pantanal{/link}, a Luz pareceu repousar dentro dela. Foi levada a {link:stormwind-city}Ventobravo{/link} e posta aos cuidados de Lorde {link:captain-grayson}Grayson{/link}, para ser guardada na {link:cathedral-of-light}Catedral da Luz{/link}.]=],
		},
		{
			title = "O Caminho do Sacrifício",
			hint = [=[Percorra o longo caminho que Lorde Grayson impõe aos paladinos do reino.]=],
			text = [=[{link:captain-grayson}Grayson{/link} não concede as honras de um paladino levianamente. A primeira provação que impõe é de sacrifício: uma doação custosa à igreja de {link:ironforge}Altaforja{/link}, em troca de um incensário sagrado guardado por seu sumo sacerdote.]=],
		},
	},
	mentions = {
